T = int(input())
for i in range(T):
	s = input()
	i = 0
	i = len(s)
	a = list(s)
	while i - 4 >= 0:
		if s[i - 4:i][0] in ['C', '?'] and s[i - 4:i][1] in ['H', '?'] and (s[i - 4:i][2] in ['E', '?']) and (s[i - 4:i][3] in ['F', '?']):
			a[i - 4] = 'C'
			a[i - 3] = 'H'
			a[i - 2] = 'E'
			a[i - 1] = 'F'
			i -= 4
		else:
			i -= 1
	for i in range(len(s)):
		if a[i] == '?':
			a[i] = 'A'
	for i in a:
		print(i, end='')
	print()
